// Hitung tenggat pajak tiap klien dan buat pesan pengingat.
// Kirim pengingat jika sisa hari tepat salah satu dari nilai ini:
const HARI_PENGINGAT = [7, 3, 1, 0];

const BULAN = ['Januari', 'Februari', 'Maret', 'April', 'Mei', 'Juni', 'Juli',
  'Agustus', 'September', 'Oktober', 'November', 'Desember'];
const HARI_MS = 24 * 60 * 60 * 1000;

// Kewajiban per jenis (PMK 81/2024). Tanggal "akhir" = akhir bulan.
const KEWAJIBAN = {
  'PPh Masa': [
    { label: 'Setor PPh Masa', tanggal: 15 },
    { label: 'Lapor SPT Masa PPh', tanggal: 20 },
  ],
  'PPN': [
    { label: 'Setor & Lapor SPT Masa PPN', tanggal: 'akhir' },
  ],
  'SPT Tahunan OP': [
    { label: 'Lapor SPT Tahunan Orang Pribadi', bulanTahunan: 3 },
  ],
  'SPT Tahunan Badan': [
    { label: 'Lapor SPT Tahunan Badan', bulanTahunan: 4 },
  ],
};

// "Hari ini" dalam WIB (UTC+7), disimpan sebagai tengah malam UTC.
const wib = new Date(Date.now() + 7 * 60 * 60 * 1000);
const hariIni = Date.UTC(wib.getUTCFullYear(), wib.getUTCMonth(), wib.getUTCDate());

// Tenggat yang jatuh di hari Sabtu/Minggu bergeser ke hari kerja berikutnya.
// Catatan: libur nasional belum dihitung.
function geserAkhirPekan(t) {
  let d = new Date(t);
  while (d.getUTCDay() === 0 || d.getUTCDay() === 6) d = new Date(d.getTime() + HARI_MS);
  return d.getTime();
}

function tenggatBulanan(k, tahun, bulan) {
  const tgl = k.tanggal === 'akhir' ? Date.UTC(tahun, bulan + 1, 0) : Date.UTC(tahun, bulan, k.tanggal);
  const masa = new Date(Date.UTC(tahun, bulan - 1, 1));
  return {
    tenggat: geserAkhirPekan(tgl),
    periode: `Masa ${BULAN[masa.getUTCMonth()]} ${masa.getUTCFullYear()}`,
  };
}

function tenggatTahunan(k, tahun) {
  return {
    tenggat: geserAkhirPekan(Date.UTC(tahun, k.bulanTahunan, 0)),
    periode: `Tahun Pajak ${tahun - 1}`,
  };
}

// Tenggat terdekat yang belum lewat.
function tenggatBerikutnya(k) {
  const d = new Date(hariIni);
  const y = d.getUTCFullYear();
  const m = d.getUTCMonth();
  const kandidat = k.bulanTahunan
    ? [tenggatTahunan(k, y), tenggatTahunan(k, y + 1)]
    : [tenggatBulanan(k, y, m), tenggatBulanan(k, y, m + 1)];
  return kandidat.find((c) => c.tenggat >= hariIni);
}

function formatTanggal(t) {
  const d = new Date(t);
  return `${d.getUTCDate()} ${BULAN[d.getUTCMonth()]} ${d.getUTCFullYear()}`;
}

function buatPengingat(rows) {
  const hasil = [];
  for (const row of rows) {
    if (String(row.Aktif || '').trim().toLowerCase() !== 'ya') continue;
    const daftar = KEWAJIBAN[String(row.Jenis || '').trim()];
    if (!daftar) continue;

    for (const k of daftar) {
      const { tenggat, periode } = tenggatBerikutnya(k);
      const sisaHari = Math.round((tenggat - hariIni) / HARI_MS);
      if (!HARI_PENGINGAT.includes(sisaHari)) continue;

      const kapan = sisaHari === 0 ? 'HARI INI' : `${sisaHari} hari lagi`;
      const pesan = [
        `Halo ${row.Nama},`,
        '',
        `Pengingat: *${k.label}* (${periode}) jatuh tempo *${formatTanggal(tenggat)}* (${kapan}).`,
        '',
        'Mohon kirimkan dokumen yang diperlukan agar bisa segera kami proses.',
        '',
        'Salam,',
        'Akhmad - Konsultan Pajak',
        'WA 089662414552',
      ].join('\n');

      hasil.push({
        nama: row.Nama,
        email: row.Email,
        whatsapp: String(row.WhatsApp || ''),
        kewajiban: k.label,
        periode,
        tenggat: formatTanggal(tenggat),
        sisaHari,
        subjek: `Pengingat Pajak: ${k.label} - ${formatTanggal(tenggat)}`,
        pesan,
      });
    }
  }
  return hasil;
}

return buatPengingat($input.all().map((i) => i.json)).map((j) => ({ json: j }));
